import {expect, it} from '@jest/globals';
import {createChatOrchestrator} from './chatOrchestrator.js';
import {createMockProvider} from '../providers/mock/mockProvider.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {ChatSession} from '../types/session.js';

it('releases a partial allocation after beforeSession fails [spec: specs/hal-engine-config-hooks/spec.md#7]', async () => {
  const session: ChatSession = {
    sessionId: 'partial-allocation',
    userId: 'user',
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  };
  const allocations = new Set<ChatSession>();
  const failure = new Error('allocation incomplete');
  const errors: unknown[] = [];
  const orchestrator = createChatOrchestrator(
    createMockProvider(),
    new PromptBuilder({identity: 'You are HAL.'}),
    undefined,
    {
      hooks: {
        beforeSession: async current => {
          allocations.add(current);
          throw failure;
        },
        onError: async (current, error) => {
          errors.push({sameSession: current === session, sameError: error === failure, allocated: allocations.has(current)});
        },
        afterSession: async current => {
          allocations.delete(current);
        },
      },
    }
  );

  const rejected = await orchestrator.processMessage(session).catch((error: unknown) => error);

  expect({sameError: rejected === failure, errors, allocated: allocations.size, entries: session.entries}).toEqual({
    sameError: true,
    errors: [{sameSession: true, sameError: true, allocated: true}],
    allocated: 0,
    entries: [{role: 'user', content: 'hello', timestamp: '2026-01-01T00:00:00.000Z'}],
  });
});
EOF
timeout 300 npm test -- --runInBand --runTestsByPath src/orchestration/chatOrchestrator.sessionCleanup.test.ts"

